$$

$$
= \lim_{x \to 0} \frac{\sin x (1 - \cos x)}{\cos x \cdot \sin^3 x} = \lim_{x \to 0} \frac{1 - \cos x}{\cos x \cdot \sin^2 x}
$$

$$
= \lim_{x \to 0} \frac{1 - \cos x}{\cos x (1 - \cos^2 x)}
$$

$$
= \lim_{x \to 0} \frac{1 - \cos x}{\cos x (1 - \cos x)(1 + \cos x)}
$$

$$
= \lim_{x \to 0} \frac{1}{\cos x (1 + \cos x)} = \frac{1}{\cos 0 (1 + \cos 0)}
$$

$$
= \frac{1}{1(1+1)} = \frac{1}{2} \text{ (Ans.)}
$$

